// Compose the customer email after a person decides in Slack.
const c = $('Team Request In').first().json;
// The team answers through a short form (not a plain link), so a link
// preview or scanner opening the URL can never approve anything.
const d = $input.first().json.data ?? {};
const approved = d.Decision === 'Approve';
const note = String(d['Note for the customer (optional)'] ?? '').trim();
const what = String(c.request_type || 'request').replace('_', ' ');
const subject = approved
  ? `Your ${what} for order ${c.order_number} is approved`
  : `About your ${what} request for order ${c.order_number}`;
const body = approved
  ? `Hi,\n\nGood news: a member of our team has approved your ${what} for order ${c.order_number}. ` +
    `We will send the next steps (and a return label, if one is needed) shortly. Refunds reach the original payment method within 5 to 7 working days.\n\n` +
    (note ? `${note}\n\n` : '') + `Thanks for shopping with us,\nFernhill Outdoor Supply`
  : `Hi,\n\nThank you for your patience. We have reviewed your ${what} request for order ${c.order_number} and cannot approve it as it stands. ` +
    `A member of our team will reply personally within one working day to explain and to find another way to help.\n\n` + (note ? `${note}\n\n` : '') +
    `Fernhill Outdoor Supply`;
// Portfolio safety: only ever email test addresses, never a real person. Change this pattern before going live.
const safe = /^you\+test-[a-z]+@example\.com$/i.test(c.customer_email || '');
return [{ json: { approved, subject, body, to: c.customer_email, safe,
  status: approved ? 'Approved' : 'Rejected', now: $now.toISO() } }];

// Daily numbers for the team: volume, how much the AI handled alone, and what is waiting.
const rows = $input.all().map(i => i.json.fields).filter(Boolean)
  .filter(r => !String(r['Case ID'] || '').startsWith('test:'));
const n = rows.length;
const by = d => rows.filter(r => r.Decision === d).length;
const handover = by('Handed Over'), approval = by('Needs Approval');
const answered = n - handover - approval;
const waiting = rows.filter(r => r.Status === 'Waiting Approval');
const pct = n ? Math.round((answered / n) * 100) : 0;
const lines = [
  `:bar_chart: *Fernhill support today* (${$now.setZone('America/Los_Angeles').toFormat('d LLL')})`,
  `Conversations: *${n}*  |  Answered by the AI alone: *${answered}* (${pct}%)`,
  `Sent for approval: *${approval}*  |  Handed to a person: *${handover}*`,
  waiting.length ? `Still waiting for approval: ${waiting.map(r => `${r['Order Number'] || r['Case ID']}`).join(', ')}` : 'Nothing waiting for approval.',
];
return [{ json: { text: lines.join('\n') } }];

// Meta posts both new messages and delivery/read receipts here.
// Keep only real customer messages; receipts have no messages array.
// Voice notes, stickers, video and files can't be read: they become a short
// note, so the bot asks the customer to type, or the person in a handover sees it.
const NOTE = { audio: 'voice note', sticker: 'sticker', video: 'video', document: 'file', location: 'location' };
const out = [];
for (const item of $input.all()) {
  const m = item.json.messages?.[0];
  if (!m) continue;
  out.push({ json: {
    messageId: m.id,                                // WhatsApp's own id, used to skip repeats
    from: m.from,                                   // sender's number, digits only
    type: m.type,
    text: m.type === 'text' ? String(m.text?.body ?? '').trim()
      : m.type === 'image' ? ''
      : `[The customer sent a ${NOTE[m.type] ?? m.type + ' message'} on WhatsApp, which cannot be read here. They need to type their message instead.]`,
    mediaId: m.type === 'image' ? m.image?.id : '',
    caption: m.type === 'image' ? String(m.image?.caption ?? '').trim() : '',
    // The customer's WhatsApp profile name, shown to the team in Slack. They
    // set it themselves, so strip Slack formatting and keep it short.
    name: String(item.json.contacts?.[0]?.profile?.name ?? '').replace(/[<>*_~`]/g, '').trim().slice(0, 60),
  } });
}
return out;

