// Slack sends every message in the channel. Keep only a person's reply inside a
// case thread; skip bot posts (including this workflow's own), edits and joins.
const out = [];
for (const item of $input.all()) {
  const e = item.json.event ?? item.json;
  if (e.type !== 'message' || e.subtype || e.bot_id) continue;
  if (!e.thread_ts || e.thread_ts === e.ts) continue;
  // Slack wraps links and emails as <url|label>; send the customer plain text.
  const text = String(e.text ?? '')
    .replace(/<mailto:[^|>]+\|([^>]+)>/g, '$1')
    .replace(/<(https?:[^|>]+)\|[^>]+>/g, '$1')
    .replace(/<(https?:[^>]+)>/g, '$1')
    // Apps that post for a person (e.g. an AI assistant) add a "*Sent using* <app>"
    // footer; it is not part of the message.
    .replace(/\s*\*Sent using\*\s+[^\n]*$/i, '')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .trim();
  if (!text) continue;
  // `close` ends the handover; `close: <words>` also sets the customer's closing message.
  // Only `close` on its own or `close:` counts, so a sentence that starts with "Close" is still sent.
  const m = text.match(/^close\.?$|^close\s*:\s*([\s\S]*)$/i);
  const closing = m && (m[1] ?? '').trim() ? m[1].trim()
    : 'Thanks for your patience. Our team has marked this as resolved. If you need anything else, just message us here.';
  out.push({ json: { ts: e.ts, threadTs: e.thread_ts, text, close: Boolean(m), closing, user: e.user } });
}
return out;

// While a person has the case, the customer may answer the bot's question
// about their order email. Pick out an email only if the case has none yet.
const c = $('Find Open Handover').first().json;
const f = c.fields ?? c;
const m = String($('Prepare Message').first().json.message).match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
if (!m || f['Customer Email']) return [];
return [{ json: {
  email: m[0].toLowerCase(),
  orderNumber: String(f['Order Number'] ?? '').toUpperCase().replace(/[^A-Z0-9-]/g, ''),
  caseId: f['Case ID'],
  thread: f['Slack Thread'],
} }];

// Customers often send several short messages in a row. Each one waited
// 4 seconds; only the run for the newest unanswered message answers, with all
// of them joined, so the customer gets one reply instead of several.
const me = $('Continue With Message').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.messageId).sort((a, b) => a.id - b.id);
if (!rows.length || rows[rows.length - 1].messageId !== me.messageId) return [];
return [{ json: { from: me.from, text: rows.map(r => r.text).join('\n'), lastId: rows[rows.length - 1].id } }];
